// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 100 ether);
        Reverter caller = new Reverter();
        vm.deal(address(caller), amount);
        vm.prank(address(caller));
        c.deposit{value: amount}();
        // The adversarial counterparty reverts on receiving Ether; in the
        // reference contract withdrawAll must then revert too.
        bool ok = caller.callWithdraw(c);
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }

    function callWithdraw(ReentrancyDAO c) external returns (bool ok) {
        try c.withdrawAll() { ok = true; } catch { ok = false; }
    }
}
